        const invitePath = url.hostname === 'discord.gg' ? /^\/[A-Za-z0-9-]+\/?$/
            : /^(www\.)?discord\.com$/.test(url.hostname) ? /^\/invite\/[A-Za-z0-9-]+\/?$/ : null;
        return url.protocol === 'https:' && !url.username && !url.password && !url.port
